import{_ as t,c as a,o,ag as n}from"./chunks/framework.DZ_cNctr.js";const i="/docs/icons/chrome-install-icon.svg",u=JSON.parse('{"title":"Installing and working offline","description":"Install the viewer as a desktop app in Chrome or Edge, and keep working with no network. What that covers, and what it does not.","frontmatter":{"title":"Installing and working offline","description":"Install the viewer as a desktop app in Chrome or Edge, and keep working with no network. What that covers, and what it does not."},"headers":[],"relativePath":"install-and-offline.md","filePath":"install-and-offline.md"}'),r={name:"install-and-offline.md"};function s(l,e,d,h,c,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="installing-and-working-offline" tabindex="-1">Installing and working offline <a class="header-anchor" href="#installing-and-working-offline" aria-label="Permalink to &quot;Installing and working offline&quot;">​</a></h1><p>The viewer runs from a web page, but it does not need to stay in a browser tab and it does not need a network connection to start.</p><h2 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h2><p>Open the viewer in Chrome or Edge and click the install icon in the address bar.</p><p><img src="'+i+'" alt="The install icon in the Chrome address bar, just before the bookmark star, with the tooltip &quot;Install Find Nuclei Viewer&quot;"></p><p>There is no install button inside the viewer itself, and that is deliberate. The browser already offers one, and a second button would only compete with it.</p><p>You get the viewer in its own window, with an icon in the Dock on macOS or the Start menu on Windows. It is the same viewer and the same data. Your projects, recent images, annotations and folder permissions carry over, because the installed app and the browser tab share the same storage.</p><p>Firefox and Safari do not offer this. Safari can add the page to the Dock, but it cannot open local folders at all, so an installed Safari copy would only read remote URLs.</p><h2 id="working-with-no-network" tabindex="-1">Working with no network <a class="header-anchor" href="#working-with-no-network" aria-label="Permalink to &quot;Working with no network&quot;">​</a></h2><p>Once you have opened the viewer with a connection at least once, it keeps working without one. Launch it on a plane, open a folder from your disk, and it behaves normally.</p><p>What keeps working:</p><ul><li>The application itself, launched cold with no connection.</li><li>Any image on your own disk. Pixels come from your filesystem, so no network is involved once you have granted access to the folder.</li><li>Your projects, recent images, annotations, templates, analytics setups and viewer preferences.</li></ul><p>What does not:</p><ul><li><strong>Images at a URL.</strong> A remote dataset needs the network, including one you viewed five minutes earlier. Image data is deliberately never cached: it is often confidential, and writing it to disk on whatever machine you happen to be using would work against the point of a viewer that keeps your data local.</li><li><strong>This documentation</strong>, and the example gallery, which is a list of remote datasets.</li></ul><p>So the short version is that the viewer works offline, with your own files. It does not make your remote images available offline.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>When a new version is published you get a small notice offering to reload. It waits for you rather than swapping mid session, so you will not lose an annotation you were in the middle of drawing. Choosing &quot;Later&quot; keeps you on the version you have until you reload.</p><h2 id="a-note-on-browser-storage" tabindex="-1">A note on browser storage <a class="header-anchor" href="#a-note-on-browser-storage" aria-label="Permalink to &quot;A note on browser storage&quot;">​</a></h2><p>Your library lives in browser storage, which browsers are allowed to clear when a device runs low on space. The viewer asks for its storage to be treated as persistent, but browsers do not always agree, and installing does not guarantee it either.</p><p>In practice this is rare. It is worth knowing because it is the one way a project list can disappear, and because it is a good reason to keep your actual image data on disk rather than treating the viewer&#39;s library as the only record of it. Annotations can be exported as CSV or GeoJSON at any time.</p>',20)])])}const f=t(r,[["render",s]]);export{u as __pageData,f as default};
